  $('photo-shuffle').addEventListener('change',()=>setOptions({order:$('photo-shuffle').checked?'shuffle':'newest'}));$('photo-repeat').addEventListener('change',()=>setOptions({repeat:$('photo-repeat').checked}));$('photo-favourites-only').addEventListener('change',()=>setOptions({collection:$('photo-favourites-only').checked?'favourites':'recent'}));
  $('photo-shuffle').closest('label').hidden=true;$('photo-favourites-only').closest('label').hidden=true;
  function collectionOptions(select,includeSpecial=true){const value=select.value;select.replaceChildren();const entries=includeSpecial?[['recent','Recent photos'],['keepers','Keepers'],['all','All stored pictures'],['favourites','Favourites'],['memories','On this day']]:[];entries.concat(data.albums.map(a=>[a.id,a.name])).forEach(([id,name])=>{const option=el('option','',name);option.value=id;select.append(option);});if(Array.from(select.options).some(o=>o.value===value))select.value=value;}
  function matching(){const album=data.albums.find(a=>a.id===filter);return state.photos.filter(photo=>{const c=M.photoChoice(choices[photo.id]);if(filter==='pending'&&!photo.pending||filter==='excluded'&&!c.hidden||filter==='keepers'&&!photo.keeper||filter==='favourites'&&!c.favourite||filter==='recent'&&(photo.recent===false||photo.pending||c.hidden))return false;if(album&&!album.photos.includes(photo.id))return false;return !query||(label(photo)+' '+c.description+' '+c.caption+' '+c.taken+' '+photo.taken+' '+new Date(photo.at).toISOString().slice(0,10)).toLowerCase().includes(query);});}
  function paintGrid(){const grid=$('library-grid');grid.replaceChildren();matching().forEach(photo=>{const card=el('div','library-photo');card.setAttribute('aria-selected',String(selected.has(photo.id)));const image=el('img');image.src=photo.url;image.alt=label(photo);image.loading='lazy';const caption=el('label'),check=el('input');check.type='checkbox';check.checked=selected.has(photo.id);check.dataset.libraryPhoto=photo.id;check.onchange=()=>{check.checked?selected.add(photo.id):selected.delete(photo.id);card.setAttribute('aria-selected',String(check.checked));paintCount();};caption.append(check,el('span','',label(photo)));const tags=el('div','library-tags',[photo.keeper?'Keeper':'',photo.pending?'Pending':'',M.photoChoice(choices[photo.id]).hidden?'Excluded':'',photo.kind==='video'?'Muted clip':''].filter(Boolean).join(' · '));const edit=el('button','quiet','Edit');edit.type='button';edit.onclick=()=>{editing=photo.id;editDirty=false;$('library-edit').open=true;paintEdit();$('library-edit').scrollIntoView({block:'start'});};card.append(image,caption,tags,edit);grid.append(card);});if(!grid.children.length)grid.append(el('p','small subtle','No pictures match.'));paintCount();}
