  function paintEdit(){if(editing)photos.selectPicture(editing);const select=$('photo-choice-select');select.replaceChildren();state.photos.forEach(photo=>{const option=el('option','',label(photo)+(photo.keeper?' · Keeper':''));option.value=photo.id;select.append(option);});const photo=state.photos.find(photo=>photo.id===editing)||state.photos[0];editing=photo?photo.id:'';select.value=editing;$('library-edit-fields').hidden=!photo;if(!photo)return;const c=M.photoChoice(choices[photo.id]);$('library-crop-preview').src=photo.url;for(const [id,key]of [['library-title','title'],['library-description','description'],['library-rotation','rotation'],['library-capture-date','taken'],['library-crop-x','x'],['library-crop-y','y'],['library-seconds','seconds']])if(!editDirty&&document.activeElement!==$(id))$(id).value=key==='taken'?c.taken||photo.taken||'':c[key];if(!editDirty)$('library-auto-crop').checked=c.autoCrop;paintCrop();}
