  function paintCrop(){const photo=state.photos.find(photo=>photo.id===editing);if(!photo)return;const preview=$('library-crop-preview'),box=preview.parentElement;const choice={...M.photoChoice(choices[editing]),fit:'cover',rotation:Number($('library-rotation').value),x:Number($('library-crop-x').value),y:Number($('library-crop-y').value),customCrop:!$('library-auto-crop').checked,autoCrop:$('library-auto-crop').checked};const style=M.framing(photo,choice,data.options,box.clientWidth,box.clientHeight);preview.style.objectFit=style.fit;preview.style.objectPosition=style.position;preview.style.width=style.width+'px';preview.style.height=style.height+'px';preview.style.transform='translate(-50%,-50%) rotate('+style.rotation+'deg)';}
  for(const id of ['library-crop-x','library-crop-y'])$(id).oninput=()=>{$('library-auto-crop').checked=false;paintCrop();};$('library-rotation').onchange=paintCrop;$('library-auto-crop').onchange=paintCrop;new ResizeObserver(()=>paintCrop()).observe($('library-crop-preview').parentElement);
