  for(const id of ['library-title','library-description','library-rotation','library-capture-date','library-crop-x','library-crop-y','library-seconds','library-auto-crop'])$(id).addEventListener('input',()=>{editDirty=true;window.SkylitApp.settingsFeedback('Unsaved picture details');});
  function idsSelected(){return Array.from(selected).filter(id=>state.photos.some(photo=>photo.id===id));}
  function ensureSelection(){const ids=idsSelected();if(!ids.length)notify('Select pictures first.');return ids;}
